export function propBaseY(p) {
  switch (p.kind) {
    case 'house': return p.base;
    case 'tree': return p.y;
    case 'lamp': return p.y;
    case 'bench': return p.y + 26;
    case 'car': return p.y + 34;
    case 'mailbox': return p.y + 12;
    case 'hedge': return p.y + p.h;
    case 'fountain': return p.y + 62;
    case 'sign': return p.y + 34;
    case 'gift': return p.y + 14;
    default: return p.y;
  }
}

function drawHouse(ctx, h, t) {
  const { x, y, w, base, wall, roof, trim, door } = h;
  const roofBottom = y + h.h + 8;
  const roofTop = y - 10;
  const cx = x + w / 2;

  // roof slab
  const roofGrad = ctx.createLinearGradient(x, roofTop, x + w, roofBottom);
  roofGrad.addColorStop(0, roof);
  roofGrad.addColorStop(1, '#2f2b3d');
  ctx.fillStyle = roofGrad;
  ctx.beginPath();
  ctx.moveTo(x - 18, roofBottom);
  ctx.lineTo(x + w + 18, roofBottom);
  ctx.lineTo(x + w - 26, roofTop);
  ctx.lineTo(x + 26, roofTop);
  ctx.closePath();
  ctx.fill();

  // shingles
  ctx.save();
  ctx.clip();
  ctx.strokeStyle = 'rgba(0,0,0,0.16)';
  ctx.lineWidth = 1.4;
  for (let sy = roofTop + 18; sy < roofBottom; sy += 21) {
    ctx.beginPath();
    ctx.moveTo(x - 20, sy);
    ctx.lineTo(x + w + 20, sy);
    ctx.stroke();
  }
  ctx.fillStyle = 'rgba(255,255,255,0.05)';
  for (let i = 0; i < 7; i++) {
    ctx.fillRect(x - 10 + ((i * 71) % (w - 40)), roofTop + 12 + ((i * 37) % (h.h - 20)), 34, 2);
  }
  ctx.restore();

  // gable / ridge highlight
  ctx.strokeStyle = 'rgba(255,255,255,0.18)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(x + 26, roofTop + 1);
  ctx.lineTo(x + w - 26, roofTop + 1);
  ctx.stroke();

  // chimney
  ctx.fillStyle = '#6a5060';
  ctx.fillRect(x + w * 0.72, roofTop + 6, 34, 30);
  ctx.fillStyle = 'rgba(0,0,0,0.25)';
  ctx.fillRect(x + w * 0.72, roofTop + 6, 34, 6);
  ctx.fillStyle = 'rgba(255,255,255,0.14)';
  ctx.fillRect(x + w * 0.72, roofTop + 6, 8, 30);

  // eaves
  ctx.fillStyle = 'rgba(0,0,0,0.35)';
  ctx.fillRect(x - 18, roofBottom - 3, w + 36, 7);
  ctx.fillStyle = trim;
  ctx.fillRect(x - 18, roofBottom + 2, w + 36, 5);

  // front wall
  const wallTop = base - 86;
  const wallGrad = ctx.createLinearGradient(0, wallTop, 0, base);
  wallGrad.addColorStop(0, '#ffffff');
  wallGrad.addColorStop(0.06, wall);
  wallGrad.addColorStop(1, '#b5978f');
  ctx.fillStyle = wall;
  rr(ctx, x + 16, wallTop, w - 32, 86, 3);
  ctx.fill();
  ctx.fillStyle = wallGrad;
  ctx.globalAlpha = 0.55;
  rr(ctx, x + 16, wallTop, w - 32, 86, 3);
  ctx.fill();
  ctx.globalAlpha = 1;

  // siding
  ctx.strokeStyle = 'rgba(80,60,60,0.1)';
  ctx.lineWidth = 1;
  for (let sy = wallTop + 9; sy < base; sy += 9) {
    ctx.beginPath();
    ctx.moveTo(x + 18, sy);
    ctx.lineTo(x + w - 18, sy);
    ctx.stroke();
  }

  // door
  const doorW = 52;
  const doorH = 62;
  const doorX = cx - doorW / 2;
  const doorY = base - doorH;
  ctx.fillStyle = 'rgba(0,0,0,0.22)';
  rr(ctx, doorX - 5, doorY - 5, doorW + 10, doorH + 5, 5);
  ctx.fill();
  ctx.fillStyle = door;
  rr(ctx, doorX, doorY, doorW, doorH, 4);
  ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.14)';
  rr(ctx, doorX + 6, doorY + 6, doorW - 12, 22, 3);
  ctx.fill();
  ctx.fillStyle = '#ffd27a';
  ctx.beginPath();
  ctx.arc(doorX + doorW - 12, doorY + doorH * 0.55, 2.6, 0, TAU);
  ctx.fill();

  // windows
  for (const wx of [x + 52, x + w - 52 - 58]) {
    const wy = wallTop + 16;
    ctx.fillStyle = 'rgba(0,0,0,0.28)';
    rr(ctx, wx - 4, wy - 4, 66, 54, 4);
    ctx.fill();
    ctx.fillStyle = trim;
    rr(ctx, wx - 2, wy - 2, 62, 50, 3);
    ctx.fill();
    const glow = ctx.createLinearGradient(wx, wy, wx, wy + 46);
    glow.addColorStop(0, '#ffe4ad');
    glow.addColorStop(1, '#ffab5e');
    ctx.fillStyle = glow;
    ctx.fillRect(wx + 4, wy + 4, 50, 42);
    ctx.strokeStyle = trim;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(wx + 29, wy + 4);
    ctx.lineTo(wx + 29, wy + 46);
    ctx.moveTo(wx + 4, wy + 25);
    ctx.lineTo(wx + 54, wy + 25);
    ctx.stroke();
    ctx.fillStyle = 'rgba(255,255,255,0.55)';
    ctx.beginPath();
    ctx.moveTo(wx + 8, wy + 42);
    ctx.lineTo(wx + 24, wy + 8);
    ctx.lineTo(wx + 32, wy + 8);
    ctx.lineTo(wx + 16, wy + 42);
    ctx.closePath();
    ctx.fill();
    // porch light bleed
    const bleed = ctx.createRadialGradient(wx + 29, wy + 24, 4, wx + 29, wy + 24, 96);
    bleed.addColorStop(0, 'rgba(255,190,110,0.22)');
    bleed.addColorStop(1, 'rgba(255,190,110,0)');
    ctx.fillStyle = bleed;
    ctx.beginPath();
    ctx.arc(wx + 29, wy + 24, 96, 0, TAU);
    ctx.fill();
  }

  // porch lamp
  ctx.fillStyle = '#ffdf9e';
  ctx.beginPath();
  ctx.arc(cx, wallTop + 6, 3.6, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(255,214,140,0.5)';
  ctx.beginPath();
  ctx.arc(cx, wallTop + 6, 9, 0, TAU);
  ctx.fill();

  // steps
  ctx.fillStyle = '#b0a89a';
  rr(ctx, doorX - 10, base, doorW + 20, 9, 2);
  ctx.fill();
  ctx.fillStyle = 'rgba(0,0,0,0.16)';
  ctx.fillRect(doorX - 10, base + 5, doorW + 20, 4);

  // house number
  ctx.fillStyle = 'rgba(255,255,255,0.62)';
  ctx.font = '700 11px "Segoe UI", system-ui, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText(`${Math.round(h.drive / 4)}`, cx, wallTop + 34);

  // warm window bloom
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  for (const wx of [x + 52, x + w - 52 - 58]) {
    const g2 = ctx.createRadialGradient(wx + 29, wallTop + 41, 6, wx + 29, wallTop + 41, 130);
    g2.addColorStop(0, 'rgba(255,180,105,0.16)');
    g2.addColorStop(1, 'rgba(255,180,105,0)');
    ctx.fillStyle = g2;
    ctx.beginPath();
    ctx.arc(wx + 29, wallTop + 41, 130, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

function drawTree(ctx, p, t) {
  const s = p.s;
  const sway = Math.sin(t * 0.8 + p.x * 0.01) * 2.4 * s;
  ctx.fillStyle = 'rgba(10,16,20,0.28)';
  ctx.beginPath();
  ctx.ellipse(p.x + 6, p.y + 2, 44 * s, 15 * s, 0, 0, TAU);
  ctx.fill();

  ctx.fillStyle = '#4a3628';
  rr(ctx, p.x - 7 * s, p.y - 58 * s, 14 * s, 58 * s, 4);
  ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.1)';
  rr(ctx, p.x - 7 * s, p.y - 58 * s, 5 * s, 54 * s, 3);
  ctx.fill();

  const blobs = [
    [0, -76, 40, '#2b4735'],
    [-24, -92, 30, '#34553d'],
    [22, -96, 31, '#365a40'],
    [4, -112, 26, '#3f6648'],
    [-30, -112, 20, '#456e4c'],
    [28, -118, 19, '#4a7452'],
  ];
  for (const [dx, dy, r, col] of blobs) {
    ctx.fillStyle = col;
    ctx.beginPath();
    ctx.arc(p.x + dx * s + sway, p.y + dy * s, r * s, 0, TAU);
    ctx.fill();
  }
  ctx.fillStyle = 'rgba(180,210,150,0.18)';
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.arc(p.x + (-20 + i * 16) * s + sway, p.y + (-108 + (i % 2) * 8) * s, 8 * s, 0, TAU);
    ctx.fill();
  }
}

function drawLamp(ctx, p) {
  ctx.fillStyle = 'rgba(10,16,24,0.3)';
  ctx.beginPath();
  ctx.ellipse(p.x, p.y + 2, 20, 7, 0, 0, TAU);
  ctx.fill();

  ctx.fillStyle = '#232a3a';
  rr(ctx, p.x - 7, p.y - 14, 14, 14, 4);
  ctx.fill();
  ctx.fillStyle = '#2d3549';
  rr(ctx, p.x - 3, p.y - 108, 6, 100, 3);
  ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.14)';
  rr(ctx, p.x - 3, p.y - 108, 2, 96, 2);
  ctx.fill();
  ctx.strokeStyle = '#2d3549';
  ctx.lineWidth = 6;
  ctx.beginPath();
  ctx.moveTo(p.x, p.y - 104);
  ctx.quadraticCurveTo(p.x + 20, p.y - 112, p.x + 24, p.y - 96);
  ctx.stroke();

  ctx.fillStyle = '#38425c';
  ctx.beginPath();
  ctx.moveTo(p.x + 14, p.y - 96);
  ctx.lineTo(p.x + 34, p.y - 96);
  ctx.lineTo(p.x + 30, p.y - 84);
  ctx.lineTo(p.x + 18, p.y - 84);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#ffe6ae';
  ctx.beginPath();
  ctx.ellipse(p.x + 24, p.y - 86, 7, 4, 0, 0, TAU);
  ctx.fill();
}

function drawBench(ctx, p, t) {
  ctx.save();
  const cx = PARK.x;
  const cy = PARK.y;
  const rot = Math.atan2(cy - p.y, cx - p.x) + Math.PI / 2;
  ctx.translate(p.x, p.y);
  ctx.rotate(rot);
  ctx.fillStyle = 'rgba(10,16,20,0.26)';
  ctx.beginPath();
  ctx.ellipse(0, 8, 46, 12, 0, 0, TAU);
  ctx.fill();

  ctx.fillStyle = '#4b3b2e';
  rr(ctx, -38, -2, 7, 14, 2);
  ctx.fill();
  rr(ctx, 31, -2, 7, 14, 2);
  ctx.fill();

  ctx.fillStyle = '#8a6748';
  for (let i = 0; i < 3; i++) {
    rr(ctx, -44, -8 + i * 7, 88, 5, 2);
    ctx.fill();
  }
  ctx.fillStyle = '#9c7752';
  for (let i = 0; i < 2; i++) {
    rr(ctx, -44, -40 + i * 9, 88, 6, 2);
    ctx.fill();
  }
  ctx.fillStyle = '#4b3b2e';
  rr(ctx, -42, -36, 6, 30, 2);
  ctx.fill();
  rr(ctx, 36, -36, 6, 30, 2);
  ctx.fill();
  ctx.restore();
}

function drawCar(ctx, p) {
  ctx.save();
  ctx.translate(p.x, p.y);
  ctx.rotate(p.rot);
  ctx.fillStyle = 'rgba(10,14,22,0.32)';
  ctx.beginPath();
  ctx.ellipse(2, 16, 56, 15, 0, 0, TAU);
  ctx.fill();

  const body = ctx.createLinearGradient(0, -26, 0, 24);
  body.addColorStop(0, '#f0f3f8');
  body.addColorStop(0.18, p.body);
  body.addColorStop(1, '#20242f');
  ctx.fillStyle = body;
  rr(ctx, -54, -22, 108, 44, 14);
  ctx.fill();

  ctx.fillStyle = 'rgba(10,20,32,0.9)';
  rr(ctx, -28, -19, 56, 36, 10);
  ctx.fill();
  ctx.fillStyle = 'rgba(160,200,240,0.55)';
  rr(ctx, -24, -16, 22, 30, 6);
  ctx.fill();
  rr(ctx, 3, -16, 21, 30, 6);
  ctx.fill();

  ctx.fillStyle = '#14171f';
  for (const wx of [-34, 22]) {
    rr(ctx, wx, -24, 12, 8, 3);
    ctx.fill();
    rr(ctx, wx, 16, 12, 8, 3);
    ctx.fill();
  }
  ctx.fillStyle = '#ffe6ac';
  rr(ctx, -54, -16, 6, 10, 3);
  ctx.fill();
  rr(ctx, -54, 6, 6, 10, 3);
  ctx.fill();
  ctx.fillStyle = '#ff9b9b';
  rr(ctx, 48, -16, 6, 10, 3);
  ctx.fill();
  rr(ctx, 48, 6, 6, 10, 3);
  ctx.fill();
  ctx.restore();
}

function drawMailbox(ctx, p) {
  ctx.fillStyle = 'rgba(10,14,20,0.24)';
  ctx.beginPath();
  ctx.ellipse(p.x, p.y + 4, 12, 4, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#5a4a3c';
  rr(ctx, p.x - 2, p.y - 26, 4, 28, 2);
  ctx.fill();
  ctx.fillStyle = '#c25a58';
  rr(ctx, p.x - 11, p.y - 34, 22, 14, 6);
  ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.25)';
  rr(ctx, p.x - 9, p.y - 32, 18, 4, 2);
  ctx.fill();
  ctx.fillStyle = '#e8e2d2';
  rr(ctx, p.x + 9, p.y - 30, 3, 9, 1);
  ctx.fill();
}

function drawHedge(ctx, p) {
  ctx.fillStyle = 'rgba(10,18,14,0.24)';
  ctx.beginPath();
  ctx.ellipse(p.x + p.w / 2, p.y + p.h + 2, p.w / 2 + 6, 8, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#2f4a35';
  rr(ctx, p.x, p.y, p.w, p.h, 8);
  ctx.fill();
  for (let i = 0; i < p.w; i += 17) {
    ctx.fillStyle = i % 34 === 0 ? '#3a5a40' : '#345239';
    ctx.beginPath();
    ctx.arc(p.x + i + 8, p.y + 2, 10 + (i % 3), 0, TAU);
    ctx.fill();
  }
  ctx.fillStyle = 'rgba(200,225,170,0.14)';
  for (let i = 0; i < p.w; i += 23) {
    ctx.beginPath();
    ctx.arc(p.x + i + 5, p.y - 1, 5, 0, TAU);
    ctx.fill();
  }
}

function drawFountain(ctx, p, t) {
  const x = p.x;
  const y = p.y;
  ctx.fillStyle = 'rgba(10,16,24,0.28)';
  ctx.beginPath();
  ctx.ellipse(x, y + 52, 122, 34, 0, 0, TAU);
  ctx.fill();

  // basin
  const rim = ctx.createLinearGradient(x, y - 50, x, y + 50);
  rim.addColorStop(0, '#d8d1c1');
  rim.addColorStop(0.5, '#b3aa98');
  rim.addColorStop(1, '#8b8271');
  ctx.fillStyle = rim;
  ctx.beginPath();
  ctx.ellipse(x, y, 118, 52, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#9b9382';
  ctx.beginPath();
  ctx.ellipse(x, y + 4, 106, 44, 0, 0, TAU);
  ctx.fill();

  // water
  const water = ctx.createRadialGradient(x - 20, y - 12, 8, x, y, 100);
  water.addColorStop(0, 'rgba(150,235,230,0.95)');
  water.addColorStop(0.55, 'rgba(62,150,168,0.95)');
  water.addColorStop(1, 'rgba(28,78,104,0.98)');
  ctx.fillStyle = water;
  ctx.beginPath();
  ctx.ellipse(x, y + 4, 98, 39, 0, 0, TAU);
  ctx.fill();

  // ripples
  for (let i = 0; i < 3; i++) {
    const phase = (t * 0.32 + i / 3) % 1;
    ctx.strokeStyle = `rgba(210,255,250,${0.32 * (1 - phase)})`;
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.ellipse(x, y + 4, 26 + phase * 70, 9 + phase * 27, 0, 0, TAU);
    ctx.stroke();
  }
  ctx.fillStyle = 'rgba(200,255,245,0.5)';
  for (let i = 0; i < 5; i++) {
    const a = t * 0.6 + i * 1.3;
    ctx.beginPath();
    ctx.arc(x + Math.cos(a) * (28 + i * 12), y + Math.sin(a) * (10 + i * 5) + 4, 1.6, 0, TAU);
    ctx.fill();
  }

  // pedestal and bowl
  ctx.fillStyle = '#b9b1a0';
  rr(ctx, x - 13, y - 46, 26, 48, 5);
  ctx.fill();
  ctx.fillStyle = '#8f8776';
  rr(ctx, x + 5, y - 46, 8, 48, 4);
  ctx.fill();
  ctx.fillStyle = '#cfc7b6';
  ctx.beginPath();
  ctx.ellipse(x, y - 50, 44, 15, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#8e8675';
  ctx.beginPath();
  ctx.ellipse(x, y - 51, 36, 10, 0, 0, TAU);
  ctx.fill();

  // water jet
  ctx.strokeStyle = 'rgba(190,245,245,0.55)';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(x, y - 54);
  ctx.quadraticCurveTo(x - 26, y - 96, x - 42, y - 62);
  ctx.moveTo(x, y - 54);
  ctx.quadraticCurveTo(x + 26, y - 96, x + 42, y - 62);
  ctx.stroke();
  ctx.fillStyle = 'rgba(215,255,252,0.75)';
  ctx.beginPath();
  ctx.ellipse(x, y - 58, 5, 8 + Math.sin(t * 4) * 2, 0, 0, TAU);
  ctx.fill();

  // lily pads
  ctx.fillStyle = '#4f8a5b';
  for (const [dx, dy, r] of [[-52, 16, 11], [46, 22, 9]]) {
    ctx.beginPath();
    ctx.arc(x + dx, y + dy, r, 0.4, TAU - 0.4);
    ctx.lineTo(x + dx, y + dy);
    ctx.fill();
  }
}

function drawSign(ctx) {
  ctx.fillStyle = 'rgba(10,14,20,0.24)';
  ctx.beginPath();
  ctx.ellipse(1390, 1166, 46, 9, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#6a5038';
  ctx.fillRect(1360, 1120, 7, 48);
  ctx.fillRect(1414, 1120, 7, 48);
  ctx.fillStyle = '#8a6a49';
  rr(ctx, 1348, 1104, 84, 34, 5);
  ctx.fill();
  ctx.strokeStyle = 'rgba(255,255,255,0.25)';
  ctx.lineWidth = 1.5;
  ctx.stroke();
  ctx.fillStyle = '#ffe9c4';
  ctx.font = '700 8px "Segoe UI", system-ui, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('BROOKHAVEN', 1390, 1118);
  ctx.font = '600 6.5px "Segoe UI", system-ui, sans-serif';
  ctx.fillStyle = '#d8c7a6';
  ctx.fillText('PARK', 1390, 1128);
}

function drawGift(ctx, p, t) {
  const bob = Math.sin(t * 2 + p.idx) * 3;
  const glow = ctx.createRadialGradient(p.x, p.y - 16 + bob, 2, p.x, p.y - 16 + bob, 42);
  glow.addColorStop(0, 'rgba(255,240,200,0.34)');
  glow.addColorStop(1, 'rgba(255,220,160,0)');
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(p.x, p.y - 16 + bob, 42, 0, TAU);
  ctx.fill();

  ctx.fillStyle = 'rgba(10,16,20,0.2)';
  ctx.beginPath();
  ctx.ellipse(p.x, p.y + 2, 16, 5, 0, 0, TAU);
  ctx.fill();

  ctx.strokeStyle = '#4d7a4e';
  ctx.lineWidth = 2;
  for (const dx of [-6, 0, 6]) {
    ctx.beginPath();
    ctx.moveTo(p.x, p.y);
    ctx.quadraticCurveTo(p.x + dx * 0.6, p.y - 16 + bob, p.x + dx, p.y - 28 + bob);
    ctx.stroke();
  }
  for (const [dx, dy, r] of [[-9, -30, 6], [0, -35, 7], [9, -29, 6], [-4, -24, 5], [5, -23, 5]]) {
    ctx.fillStyle = p.hue;
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * TAU;
      ctx.beginPath();
      ctx.arc(p.x + dx + Math.cos(a) * r * 0.7, p.y + dy + bob + Math.sin(a) * r * 0.7, r * 0.6, 0, TAU);
      ctx.fill();
    }
    ctx.fillStyle = '#fff3c4';
    ctx.beginPath();
    ctx.arc(p.x + dx, p.y + dy + bob, r * 0.45, 0, TAU);
    ctx.fill();
  }
  ctx.fillStyle = 'rgba(255,255,255,0.85)';
  ctx.beginPath();
  ctx.arc(p.x + 12, p.y - 34 + bob, 1.6, 0, TAU);
  ctx.fill();
}

export function drawProp(ctx, p, t) {
  switch (p.kind) {
    case 'house': return drawHouse(ctx, p, t);
    case 'tree': return drawTree(ctx, p, t);
    case 'lamp': return drawLamp(ctx, p, t);
    case 'bench': return drawBench(ctx, p, t);
    case 'car': return drawCar(ctx, p, t);
    case 'mailbox': return drawMailbox(ctx, p, t);
    case 'hedge': return drawHedge(ctx, p, t);
    case 'fountain': return drawFountain(ctx, p, t);
    case 'sign': return drawSign(ctx, p, t);
    case 'gift': return drawGift(ctx, p, t);
    default: return undefined;
  }
}

/* ------------------------------------------------------------------ glow */

export function drawLampGlow(ctx, x, y, t) {
  const flicker = 0.9 + Math.sin(t * 5 + x) * 0.03;
  const g = ctx.createRadialGradient(x + 24, y - 86, 4, x + 24, y - 86, 190);
  g.addColorStop(0, `rgba(255,214,150,${0.3 * flicker})`);
  g.addColorStop(0.45, `rgba(255,188,110,${0.12 * flicker})`);
  g.addColorStop(1, 'rgba(255,180,100,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.ellipse(x + 24, y - 40, 120, 78, 0, 0, TAU);
  ctx.fill();

  // ground pool
  const pool = ctx.createRadialGradient(x + 24, y - 6, 6, x + 24, y - 6, 150);
  pool.addColorStop(0, `rgba(255,200,130,${0.13 * flicker})`);
  pool.addColorStop(1, 'rgba(255,200,130,0)');
  ctx.fillStyle = pool;
  ctx.beginPath();
  ctx.ellipse(x + 24, y - 4, 130, 56, 0, 0, TAU);
  ctx.fill();
}

export function drawBeacon(ctx, x, y, t, color = '255,140,180') {
  const pulse = 0.5 + Math.sin(t * 2.6) * 0.3;
  const g = ctx.createLinearGradient(0, y - 150, 0, y - 20);
  g.addColorStop(0, `rgba(${color},0)`);
  g.addColorStop(0.65, `rgba(${color},${0.055 + pulse * 0.03})`);
  g.addColorStop(1, `rgba(${color},${0.14 + pulse * 0.05})`);
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(x - 20, y - 20);
  ctx.lineTo(x - 6, y - 150);
  ctx.lineTo(x + 6, y - 150);
  ctx.lineTo(x + 20, y - 20);
  ctx.closePath();
  ctx.fill();

  const hx = x;
  const hy = y - 150 + Math.sin(t * 2.6) * 5;
  ctx.fillStyle = `rgba(${color},${0.55 + pulse * 0.35})`;
  heartPath(ctx, hx, hy - 6, 1.1);
  ctx.fill();
}

/* Small synthesised soundscape — no audio files, no network. */

export class Sound {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = localStorage.getItem('sorry-muted') === '1';
    this.stepTimer = 0;
  }

  get ready() {
    return Boolean(this.ctx);
  }

  unlock() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.55;
    this.master.connect(this.ctx.destination);
    this.startRain();
    this.startPad();
  }

  startRain() {
    const ctx = this.ctx;
    const buffer = ctx.createBuffer(1, ctx.sampleRate * 3, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < data.length; i++) {
      const white = Math.random() * 2 - 1;
      last = last * 0.96 + white * 0.04;
      data[i] = last * 2.6;
    }
    const src = ctx.createBufferSource();
    src.buffer = buffer;
    src.loop = true;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 1400;
    const gain = ctx.createGain();
    gain.gain.value = 0.16;
    src.connect(filter).connect(gain).connect(this.master);
    src.start();

    // distant rain hiss
    const hiss = ctx.createBufferSource();
    hiss.buffer = buffer;
    hiss.loop = true;
    const hp = ctx.createBiquadFilter();
    hp.type = 'highpass';
    hp.frequency.value = 2600;
    const hg = ctx.createGain();
    hg.gain.value = 0.022;
    hiss.connect(hp).connect(hg).connect(this.master);
    hiss.start();
  }

  startPad() {
    const ctx = this.ctx;
    const bus = ctx.createGain();
    bus.gain.value = 0.09;
    bus.connect(this.master);

    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 640;
    filter.Q.value = 0.6;
    filter.connect(bus);

    const notes = [110, 164.81, 220, 277.18];
    notes.forEach((freq, i) => {
      const osc = ctx.createOscillator();
      osc.type = i % 2 ? 'sine' : 'triangle';
      osc.frequency.value = freq;
      osc.detune.value = (i - 1.5) * 4;

      const g = ctx.createGain();
      g.gain.value = i === 0 ? 0.5 : 0.22 / (i * 0.5 + 0.5);

      // slow wandering amplitude
      const lfo = ctx.createOscillator();
      lfo.frequency.value = 0.04 + i * 0.017;
      const lfoGain = ctx.createGain();
      lfoGain.gain.value = 0.14;
      lfo.connect(lfoGain).connect(g.gain);
      lfo.start();

      osc.connect(g).connect(filter);
      osc.start();
    });

    // gentle tape wobble
    const wobble = ctx.createOscillator();
    wobble.frequency.value = 0.09;
    const wobbleGain = ctx.createGain();
    wobbleGain.gain.value = 70;
    wobble.connect(wobbleGain).connect(filter.frequency);
    wobble.start();

    this.padBus = bus;
  }

  setMuted(muted) {
    this.muted = muted;
    localStorage.setItem('sorry-muted', muted ? '1' : '0');
    if (this.master && this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.linearRampToValueAtTime(muted ? 0 : 0.55, this.ctx.currentTime + 0.2);
    }
  }

  tone({ freq = 440, type = 'sine', dur = 0.3, gain = 0.12, slide = null, delay = 0 }) {
    if (!this.ctx || this.muted) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    const g = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(20, slide), t0 + dur);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(gain, t0 + 0.015);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(g).connect(this.master);
    osc.start(t0);
    osc.stop(t0 + dur + 0.05);
  }

  chime() {
    [523.25, 659.25, 783.99, 1046.5].forEach((f, i) => {
      this.tone({ freq: f, type: 'sine', dur: 0.55, gain: 0.075, delay: i * 0.075 });
    });
  }

  wrong() {
    this.tone({ freq: 220, type: 'triangle', dur: 0.42, gain: 0.1, slide: 130 });
    this.tone({ freq: 164, type: 'sine', dur: 0.5, gain: 0.07, slide: 98, delay: 0.08 });
  }

  pickup() {
    this.tone({ freq: 880, type: 'sine', dur: 0.18, gain: 0.06 });
    this.tone({ freq: 1320, type: 'sine', dur: 0.26, gain: 0.05, delay: 0.07 });
  }

  click() {
    this.tone({ freq: 640, type: 'triangle', dur: 0.08, gain: 0.05 });
  }

  win() {
    const notes = [392, 523.25, 659.25, 783.99, 1046.5, 1318.5];
    notes.forEach((f, i) => this.tone({ freq: f, type: 'triangle', dur: 0.7, gain: 0.06, delay: i * 0.11 }));
  }

  lose() {
    const notes = [329.63, 293.66, 246.94, 196];
    notes.forEach((f, i) => this.tone({ freq: f, type: 'sine', dur: 0.8, gain: 0.07, delay: i * 0.18 }));
  }

  step() {
    if (!this.ctx || this.muted) return;
    const ctx = this.ctx;
    const buffer = ctx.createBuffer(1, 512, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / data.length);
    const src = ctx.createBufferSource();
    src.buffer = buffer;
    const bp = ctx.createBiquadFilter();
    bp.type = 'bandpass';
    bp.frequency.value = 900 + Math.random() * 400;
    const g = ctx.createGain();
    g.gain.value = 0.05;
    src.connect(bp).connect(g).connect(this.master);
    src.start();
  }
}

