  rr(ctx, -55, -14, 5, 9, 2);
  ctx.fill();
  rr(ctx, -55, 5, 5, 9, 2);
  ctx.fill();
  ctx.fillStyle = '#ff9b9b';
  rr(ctx, 50, -14, 5, 9, 2);
  ctx.fill();
  rr(ctx, 50, 5, 5, 9, 2);
