  rr(ctx, -54, -26, 108, 52, 8);
  ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.24)';
  for (let x = -44; x < 54; x += 24) {
    for (let y = -20; y < 22; y += 20) {
      ctx.fillRect(x + (y % 40 === 0 ? 12 : 0), y, 12, 10);
