#dialogue {
  position: fixed;
  left: 50%;
  bottom: calc(18px + var(--sa-bottom));
  transform: translateX(-50%) translateY(0);
  width: min(860px, calc(100vw - 24px));
  display: flex;
  gap: 16px;
  padding: 16px;
  border-radius: 22px;
  background: linear-gradient(160deg, rgba(29, 36, 58, 0.96), rgba(16, 20, 34, 0.97));
  border: 1px solid rgba(255, 255, 255, 0.16);
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(14px);
  z-index: 20;
  animation: panelIn 0.28s cubic-bezier(0.2, 0.9, 0.25, 1.05);
}

@keyframes panelIn {
  from { transform: translateX(-50%) translateY(18px); opacity: 0; }
  to { transform: translateX(-50%) translateY(0); opacity: 1; }
}

.portrait {
  flex: 0 0 auto;
  width: 112px;
  height: 112px;
  border-radius: 18px;
  overflow: hidden;
  background: radial-gradient(circle at 50% 35%, #3a4a72, #1a2033 72%);
  border: 1px solid rgba(255, 255, 255, 0.14);
  position: relative;
}
.portrait::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 55%, rgba(10, 12, 20, 0.55));
  pointer-events: none;
}
.portrait canvas { width: 100%; height: 100%; display: block; }

.dlg-body { flex: 1 1 auto; min-width: 0; }

.dlg-head {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin-bottom: 4px;
}

.dlg-name {
  margin: 0;
  font-size: 17px;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.dlg-mood {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: #ffb0c4;
  background: rgba(255, 111, 156, 0.13);
  border: 1px solid rgba(255, 111, 156, 0.3);
  padding: 2px 8px;
  border-radius: 999px;
}

.dlg-line {
  margin: 0 0 12px;
  font-size: 14.5px;
  line-height: 1.45;
  color: #e8e3d8;
}

.dlg-options {
  display: grid;
  gap: 7px;
}

.option {
  display: flex;
  align-items: center;
  gap: 10px;
  text-align: left;
  width: 100%;
  padding: 10px 13px;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.05);
  color: var(--ink);
  font: inherit;
  font-size: 13.5px;
  line-height: 1.35;
  cursor: pointer;
  transition: background 0.18s ease, border-color 0.18s ease, transform 0.12s ease;
}
.option:hover { background: rgba(93, 140, 255, 0.18); border-color: rgba(120, 160, 255, 0.5); }
.option:active { transform: scale(0.99); }
.option:focus-visible { outline: 2px solid var(--blue); outline-offset: 2px; }

.option .key {
  flex: 0 0 auto;
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.16);
  font-size: 11px;
  font-weight: 800;
  color: #dce6ff;
}

.option.ok { animation: okFlash 0.5s ease; }
.option.bad { animation: badFlash 0.5s ease; }

@keyframes okFlash { 0%, 100% { background: rgba(255, 255, 255, 0.05); } 40% { background: rgba(90, 210, 160, 0.3); } }
@keyframes badFlash { 0%, 100% { background: rgba(255, 255, 255, 0.05); } 40% { background: rgba(255, 90, 90, 0.3); } }

.dlg-continue {
  margin-top: 10px;
  padding: 9px 20px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.24);
  background: linear-gradient(180deg, #5b93ff, #2f63d8);
  color: #fff;
  font: inherit;
  font-weight: 700;
  font-size: 13.5px;
  cursor: pointer;
  box-shadow: 0 8px 20px rgba(40, 90, 200, 0.4);
}
.dlg-continue:active { transform: scale(0.97); }

/* ---------- screens ---------- */
.screen {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
  padding: calc(18px + var(--sa-top)) 18px calc(18px + var(--sa-bottom));
  z-index: 30;
  background:
    radial-gradient(ellipse at 50% 120%, rgba(255, 140, 110, 0.22), transparent 55%),
    radial-gradient(ellipse at 50% -10%, rgba(70, 110, 210, 0.25), transparent 55%),
    rgba(8, 10, 18, 0.62);
  backdrop-filter: blur(7px) saturate(1.05);
  animation: fadeIn 0.4s ease;
}

@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }

.screen-card {
  width: min(520px, 100%);
  text-align: center;
  padding: 30px 26px 24px;
  border-radius: 28px;
  background: linear-gradient(165deg, rgba(33, 41, 66, 0.88), rgba(13, 17, 30, 0.92));
  border: 1px solid rgba(255, 255, 255, 0.16);
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.65), inset 0 1px 0 rgba(255, 255, 255, 0.1);
  position: relative;
  overflow: hidden;
}

.screen-card::before {
  content: "";
  position: absolute;
  inset: -40% -20% auto;
  height: 70%;
  background: radial-gradient(ellipse at 50% 0%, rgba(255, 175, 120, 0.18), transparent 70%);
  pointer-events: none;
}

.kicker {
  margin: 0 0 10px;
  font-size: 10.5px;
  letter-spacing: 0.26em;
  text-transform: uppercase;
  color: #9fb0d4;
}

.logo {
  margin: 0;
  font-family: "Arial Black", "Arial Bold", Gadget, system-ui, sans-serif;
  font-size: clamp(42px, 12vw, 68px);
  line-height: 0.92;
  letter-spacing: -0.015em;
  transform: rotate(-1.6deg);
  text-shadow: 0 6px 0 rgba(0, 0, 0, 0.25), 0 20px 50px rgba(0, 0, 0, 0.5);
}

.logo span {
  background: linear-gradient(180deg, #ffd791 10%, #ff8a6b 60%, #ff5d7e);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 4px 18px rgba(255, 110, 100, 0.35));
}

.tagline {
  margin: 12px 0 0;
  font-size: 13px;
  font-style: italic;
  color: #ffc4b4;
  letter-spacing: 0.04em;
}

