  await page.waitForFunction(() => document.fonts.status === 'loaded');
  const b = page.getByRole('button',{name:'Start',exact:true});
  console.log(name, 'start', await b.isVisible(), await b.isEnabled());
  try { await b.click({trial:true, timeout:2000}); console.log(name,'trial ok'); }
  catch(e) { console.log(name,'trial fail', e.name, e.message.split('\n').slice(0,10).join(' | ')); }
  await page.waitForTimeout(1000);
  await page.screenshot({path: `/tmp/opencode/${name}.png`});
  await page.close();
}
await browser.close();
